"""
    Helper function,returns Dict representing query names

    Dict is indexed by tuples of (table, column) names for fields which
      belong to the listed queries

    Keyword Parameters:
    source_id  -- Sting, identifying the project table to return
      columns for
    dwsupport_model  -- Dict, representing current DWSupport schema

    >>> # Check return format
    >>> from pprint import pprint
    >>> test_table = 'catch_fact'
    >>> model = { 'tables': [ { 'name': 'catch_fact', 'type': 'fact'
    ...                        ,'project': 'trawl'}
    ...                      ,{ 'name': 'depth_dim', 'type': 'dimension'
    ...                        ,'project': 'warehouse'}
    ...                      ,{ 'name': 'operation_fact', 'type': 'fact'
    ...                        ,'project': 'acoustics'}]
    ...          ,'associations': [ { 'table': 'catch_fact'
    ...                              ,'parent': 'depth_dim'}
    ...                            ,{ 'table': 'operation_fact'
    ...                              ,'parent': 'depth_dim'}]
    ...          ,'variables': [ { 'table': 'catch_fact'
    ...                           ,'column': 'retained_kg'}
    ...                         ,{ 'table': 'catch_fact'
    ...                           ,'column': 'retained_ct'}
    ...                         ,{ 'table': 'depth_dim'
    ...                           ,'column': 'meters'}
    ...                         ,{ 'table': 'depth_dim'
    ...                           ,'column': 'fathoms'}
    ...                         ,{ 'table': 'operation_fact'
    ...                           ,'column': 'frequency_mhz'}]
    ...          ,'variable_custom_identifiers': [
    ...               { 'id': 'freq', 'table': 'operation_fact'
    ...                ,'column': 'frequency_mhz'}]
    ...          ,'queries': [
    ...               {'name': 'core',
    ...                'table': 'catch_fact',
    ...                'variables': {'depth_dim': ['meters'],
    ...                              'catch_fact': ['retained_kg']}
    ...               }]
    ... }
    >>> out = _get_query_names_by_table_column_tuple(test_table, model)
    >>> pprint(out)
    {('catch_fact', 'retained_kg'): ['core'], ('depth_dim', 'meters'): ['core']}
    """
def _get_query_names_by_table_column_tuple(
    table_name: Any, dwsupport_model: Any
) -> object {
    query_names_by_table_column_tuple = `dict();
    for query in dwsupport_model['queries'] {
        if (query['table'] == table_name) {
            query_name = query['name'];
            for (variable_table, columns) in query['variables'].items() {
                for variable_column in columns {
                    key = (variable_table, variable_column);
                    try {
                        query_names_by_table_column_tuple[key].append(query_name);
                    } except KeyError {
                        query_names_by_table_column_tuple[key] = [query_name];
                    }
                }
            }
        }
    }
    return query_names_by_table_column_tuple;
}

""" Create a string representation of a numpy array with less precision
    than the default.

    Parameters
    ----------
    arr : array
        Array to be converted to a string

    precision : int
        Number of significant digit to display each value.

    Returns
    -------
    str
        Nice string representation of the array.
    """
def format_array(arr: Any, precision: Any = 4) -> object {
    if (arr is None) {
        return "";
    }
    formatting_str = "{0:." + str(precision) + "g}";
    str_values = [formatting_str.format(float(val)) for val in arr];
    content = ", ".join(str_values);
    return ("[" + content + "]");
}

"""
    Return an array of board positions/indices that contain "None".

    Input:
         board_state:
            (0,1,0,None,None,None,None,None,None)
         a tuple of the board's state

    Output:
         an array of board positions/indices of possible moves:
            [3,4,5,6,7,8]
    """
def get_available_moves(board_state: Any) -> object {
    possible_moves = [];
    for (i, board_position) in enumerate(board_state) {
        if (board_position == None) {
            possible_moves.append(i);
        }
    }
    return possible_moves;
}

