"""
    antiderivative of the Birch Murnaghan E(V)
    """
def antiderE(V0: Any, B0: Any, B0pr: Any, V: Any) -> object {
    antider = (
        (
            9
            * B0
            * V0
            * (
                (-((-6 + B0pr) * V) - (((-4 + B0pr) * (V0 ** 2)) / V))
                + (3 * (-14 + (3 * B0pr)) * V0 * ((V0 / V) ** (1 / 3)))
                + (3 * (-16 + (3 * B0pr)) * V * ((V0 / V) ** (2 / 3)))
            )
        )
        / 16
    );
    return antider;
}

"""
         Precomputes the future padded size.

         Parameters
         ----------
         M, N : int
             input size

         Returns
         -------
         M, N : int
             padded size
    """
def compute_padding(M: Any, N: Any, J: Any) -> object {
    M_padded = (((M + (2 ** J)) // (2 ** J)) + 1) * (2 ** J);
    N_padded = (((N + (2 ** J)) // (2 ** J)) + 1) * (2 ** J);
    return (M_padded, N_padded);
}

